`timescale 1ns/1ps
package dvbench_pkg;
import uvm_pkg::*;
`include "uvm_macros.svh"
class dvbench_transaction extends uvm_sequence_item;
    logic [151:0] input_state;
    logic [313:0] actual_state;
    logic [313:0] expected_state;
    logic [313:0] compare_mask;
    time delay_ns;
    `uvm_object_utils(dvbench_transaction)
    function new(string name="dvbench_transaction"); super.new(name); endfunction
endclass
class dvbench_sequence extends uvm_sequence #(dvbench_transaction);
    `uvm_object_utils(dvbench_sequence)
    function new(string name="dvbench_sequence"); super.new(name); endfunction
    task send(time delay_ns, logic [151:0] state);
        dvbench_transaction request;
        request=dvbench_transaction::type_id::create("request");
        start_item(request); request.delay_ns=delay_ns; request.input_state=state; finish_item(request);
    endtask
    task overlap_cycle(logic reset_value, logic allocate_value, logic [5:0] route,
                       logic valid_value, logic [4:0] tag, logic [127:0] data,
                       logic [2:0] count, logic done_value, logic error_value);
        logic [151:0] state;
        state={1'b0,data,4'((1<<count)-1),count,done_value,error_value,
               route,allocate_value,reset_value,tag,valid_value};
        send(5,state);
        state[151]=1;
        send(5,state);
    endtask
    task allocation_payload_overlap();
        for(int route=0;route<64;route++) begin
            repeat(2) overlap_cycle(1,0,0,0,0,0,0,0,0);
            repeat(4) overlap_cycle(0,0,0,0,0,0,0,0,0);
            overlap_cycle(0,1,0,0,0,0,0,0,0);
            overlap_cycle(0,1,6'(route),1,0,128'h12345678,1,1,0);
            repeat(3) overlap_cycle(0,0,0,0,0,0,0,0,0);
            overlap_cycle(0,0,0,1,1,128'hfedcba9876543210,2,route[0],1);
            repeat(48) overlap_cycle(0,0,0,0,0,0,0,0,0);
        end
    endtask
