class dvbench_driver extends uvm_driver #(dvbench_transaction);
    virtual dvbench_if vif;
    `uvm_component_utils(dvbench_driver)
    function new(string name,uvm_component parent); super.new(name,parent); endfunction
    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        if(!uvm_config_db#(virtual dvbench_if)::get(this,"","vif",vif)) `uvm_fatal("VIF","Missing interface")
    endfunction
    task run_phase(uvm_phase phase);
        forever begin
            seq_item_port.get_next_item(req);
            #(req.delay_ns); vif.input_state=req.input_state;
            seq_item_port.item_done();
        end
    endtask
endclass
class dvbench_predictor extends uvm_component;
    virtual dvbench_if vif;
    `uvm_component_utils(dvbench_predictor)
    function new(string name,uvm_component parent); super.new(name,parent); endfunction
    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        if(!uvm_config_db#(virtual dvbench_if)::get(this,"","vif",vif)) `uvm_fatal("VIF","Missing interface")
    endfunction
    function void predict(dvbench_transaction observed);
        observed.expected_state=vif.expected_state;
        observed.compare_mask=vif.compare_mask;
    endfunction
endclass
class dvbench_monitor extends uvm_component;
    virtual dvbench_if vif;
    dvbench_predictor predictor;
    uvm_analysis_port#(dvbench_transaction) observations;
    `uvm_component_utils(dvbench_monitor)
    function new(string name,uvm_component parent); super.new(name,parent); observations=new("observations",this); endfunction
    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        predictor=dvbench_predictor::type_id::create("predictor",this);
        if(!uvm_config_db#(virtual dvbench_if)::get(this,"","vif",vif)) `uvm_fatal("VIF","Missing interface")
    endfunction
    task run_phase(uvm_phase phase);
        dvbench_transaction observed;
        forever begin
            @(vif.sample_ready);
            observed=dvbench_transaction::type_id::create("observed");
            observed.input_state=vif.input_state;
            observed.actual_state=vif.actual_state;
            predictor.predict(observed);
            observations.write(observed);
        end
    endtask
endclass
class dvbench_scoreboard extends uvm_component;
    uvm_analysis_imp#(dvbench_transaction,dvbench_scoreboard) observations;
    longint checked_points, mismatched_points;
    `uvm_component_utils(dvbench_scoreboard)
    covergroup response_coverage with function sample(integer ones, bit mismatch);
        option.per_instance=1;
        response_bits: coverpoint ones { bins zero={0}; bins nonzero={[1:4096]}; }
        comparison: coverpoint mismatch { bins correct={0}; bins incorrect={1}; }
    endgroup
    function new(string name,uvm_component parent);
        super.new(name,parent); observations=new("observations",this); response_coverage=new();
    endfunction
    function void write(dvbench_transaction observed);
        bit mismatch;
        mismatch=(observed.actual_state & observed.compare_mask) !== (observed.expected_state & observed.compare_mask);
        if($isunknown(observed.expected_state & observed.compare_mask)) mismatch=1;
        checked_points++;
        response_coverage.sample($countones(observed.expected_state & observed.compare_mask),mismatch);
        if(mismatch) begin
            mismatched_points++;
            if(mismatched_points<=20) `uvm_error("PORT_MISMATCH",$sformatf("point=%0d actual=%h expected=%h mask=%h",checked_points,observed.actual_state,observed.expected_state,observed.compare_mask))
        end
    endfunction
    function void check_phase(uvm_phase phase);
        super.check_phase(phase);
        if(checked_points==0) `uvm_error("VACUOUS","No sampled comparisons")
        `uvm_info("CHECK_COUNTS",$sformatf("points=%0d mismatches=%0d",checked_points,mismatched_points),UVM_NONE)
    endfunction
    function void report_phase(uvm_phase phase);
        super.report_phase(phase);
        if(checked_points>0 && mismatched_points==0 && uvm_report_server::get_server().get_severity_count(UVM_ERROR)==0 && uvm_report_server::get_server().get_severity_count(UVM_FATAL)==0)
            $display("DVBench_COMPLETED");
    endfunction
endclass
class dvbench_env extends uvm_env;
    uvm_sequencer#(dvbench_transaction) sequencer;
    dvbench_driver driver;
    dvbench_monitor monitor;
    dvbench_scoreboard scoreboard;
    `uvm_component_utils(dvbench_env)
    function new(string name,uvm_component parent); super.new(name,parent); endfunction
    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        sequencer=uvm_sequencer#(dvbench_transaction)::type_id::create("sequencer",this);
        driver=dvbench_driver::type_id::create("driver",this);
        monitor=dvbench_monitor::type_id::create("monitor",this);
        scoreboard=dvbench_scoreboard::type_id::create("scoreboard",this);
    endfunction
    function void connect_phase(uvm_phase phase);
        driver.seq_item_port.connect(sequencer.seq_item_export);
        monitor.observations.connect(scoreboard.observations);
    endfunction
endclass
class dvbench_test extends uvm_test;
    dvbench_env env;
    `uvm_component_utils(dvbench_test)
    function new(string name,uvm_component parent); super.new(name,parent); endfunction
    function void build_phase(uvm_phase phase); super.build_phase(phase); env=dvbench_env::type_id::create("env",this); endfunction
    task run_phase(uvm_phase phase);
        dvbench_sequence sequence_object;
        phase.raise_objection(this);
        sequence_object=dvbench_sequence::type_id::create("sequence_object");
        sequence_object.start(env.sequencer);
        #10;
        phase.drop_objection(this);
    endtask
endclass
endpackage
